package com.buct.course.login

/**
 * 北化统一认证/教务 (*.buct.edu.cn) 的 TLS 证书链（DER Base64 内嵌）。
 * 服务器证书由 GlobalSign RSA OV SSL CA 2018 签发，根为 GlobalSign Root CA - R3。
 * Android 部分系统信任库不含 R3 根，导致握手失败，故内嵌此链。
 */
internal object BuctCertificates {
    // GlobalSign RSA OV SSL CA 2018（中间证书）
    val INTERMEDIATE_B64: String = """

"""

    // GlobalSign Root CA - R3
    val ROOT_B64: String = """

"""


    // ZeroSSL ECC DV SSL CA 2（公网认证入口 experimental-auth-endpoint 的中间证书）
    val ZEROSSL_INTERMEDIATE_B64: String = """

"""

    // Sectigo Public Server Authentication Root E46（公网认证入口的信任点）
    val SECTIGO_E46_B64: String = """

"""
}
